export function buildAdditionalLessons(base: FounderMission[]): FounderMission[] {
  return outlines.map((outline) => {
    const artwork = base.find((mission) => mission.id === outline.art)!;
    const originalPrompt = base.flatMap((mission) => mission.canvasPrompts)
      .find((prompt) => prompt.sectionId === outline.canvas)!;
    const rounds: SimulatorRound[] = outline.decisions.map(([situation, best, bestFeedback, tempting, temptingFeedback, risky, riskyFeedback], index) => {
      const choices = [
        { id: 'evidence', label: best, description: 'Use the lesson to make the decision.', effects: { evidence: 22, cash: -5, trust: 15 }, feedback: bestFeedback },
        { id: 'shortcut', label: tempting, description: 'Consider the tradeoff before choosing.', effects: { evidence: 3, cash: -15, trust: -5 }, feedback: temptingFeedback },
        { id: 'risk', label: risky, description: 'Think about the effect on the business.', effects: { evidence: -8, cash: -22, trust: -15 }, feedback: riskyFeedback },
      ];
      // Vary positions so a student has to read each decision.
      return { id: `${outline.id}-decision-${index + 1}`, situation, choices: [...choices.slice(index), ...choices.slice(0, index)] };
    });
    return {
      id: outline.id, order: 0, title: outline.title, shortTitle: outline.title,
      tagline: outline.tagline, estimatedMinutes: 18, icon: artwork.icon,
      comicPanels: outline.chapters.map(([title, explanation, example, takeaway], index) => ({
        imageUrl: artwork.comicPanels[index].imageUrl,
        alt: artwork.comicPanels[index].alt,
        title, text: `Let’s work through ${title.toLowerCase()} together.`, explanation, example, takeaway,
      })),
      simulator: {
        title: `${outline.title}: Decision Lab`, intro: outline.tagline,
        scenario: 'Make three decisions using the lesson’s customer evidence, resource limits, and delivery promises.',
        meters: [
          { id: 'evidence', label: 'Useful evidence', emoji: '🔎', initial: 25, color: 'emerald' },
          { id: 'cash', label: 'Cash protected', emoji: '💵', initial: 80, color: 'amber' },
          { id: 'trust', label: 'Customer & team trust', emoji: '🌱', initial: 45, color: 'blue' },
        ], rounds, endMessage: 'Compare the effects of your decisions. A useful next move protects resources, creates evidence, and honors the promise to customers.',
      },
      quiz: outline.checks.map(([question, correct, wrong1, wrong2, wrong3, explanation], index) => {
        const values = [correct, wrong1, wrong2, wrong3];
        const rotated = [...values.slice(index), ...values.slice(0, index)];
        const options = rotated.map((text, i) => ({ id: String(i), text }));
        return { id: `${outline.id}-q${index + 1}`, question, options, correctId: String(rotated.indexOf(correct)), explanation };
      }),
      teachBack: {
        conceptName: outline.title.toLowerCase(),
        keyFacts: outline.chapters.slice(0, 4).map((chapter) => chapter[3]),
        misconceptions: outline.misconceptions,
      },
      canvasPrompts: [{ ...originalPrompt, prompt: outline.canvasPrompt }],
      rewards: { xp: 100, bamboo: 15 },
      sources: outline.art === 'funding-the-business' ? [FUNDING, MARKET] : outline.art === 'building-the-team' ? [TEAM, LEAN] : [LEAN, MARKET],
    };
  });
}
